def is_valid_digit(line):
    """Check if a line contains only digits."""
    return line.isdigit()

def main():
    """Read a single line of input from the user and check if it contains only digits."""
    user_input = input("Please enter a line of digits: ")

    if is_valid_digit(user_input):
        print("Valid")
    else:
        print("Invalid")

# Call the main function to start the program
